import { describe, expect, it } from "vitest";
import { createInvoice } from "./create";

describe("currency fallback", () => {
  it("uses the explicit currency", async () => {
    expect((await createInvoice(body({ currency: "eur" }), customer("GBP"))).currency).toBe("EUR");
  });
  it("falls back to the customer's currency", async () => {
    expect((await createInvoice(body({}), customer("GBP"))).currency).toBe("GBP");
  });
  it("falls back to USD", async () => {
    expect((await createInvoice(body({}), customer(undefined))).currency).toBe("USD");
  });
});

steps.text:
Confirmed: Stripe treats JPY as zero-decimal, and our `toMinorUnits` multiplies by 100 unconditionally. That matches the ticket. Proposed fix:

```ts
const ZERO_DECIMAL = new Set(["JPY", "KRW", "VND"]);
export function toMinorUnits(amount: number, currency: string) {
  return ZERO_DECIMAL.has(currency) ? Math.round(amount) : Math.round(amount * 100);
}
```
